using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Security.AccessControl;
using System.Security.Cryptography;
using System.Security.Principal;
using System.Text;
using System.Text.RegularExpressions;

namespace AntiDPI.Setup
{
    internal static class Payload
    {
        internal const long MaximumZipBytes = 64L * 1024 * 1024;
        internal const long MaximumExpandedBytes = 512L * 1024 * 1024;
        private static readonly Regex DeviceName = new Regex(
            @"^(CON|PRN|AUX|NUL|COM[1-9\u00b9\u00b2\u00b3]|LPT[1-9\u00b9\u00b2\u00b3])(?:\.|$)",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

        internal static byte[] ReadEmbedded(Assembly assembly)
        {
            using (Stream source = assembly.GetManifestResourceStream(BuildInfo.ResourceName))
            {
                if (source == null) throw new InvalidDataException("В установщике отсутствует архив программы.");
                if (source.Length > MaximumZipBytes) throw new InvalidDataException("Встроенный архив слишком велик.");
                using (MemoryStream copy = new MemoryStream())
                {
                    source.CopyTo(copy);
                    return copy.ToArray();
                }
            }
        }

        internal static string Sha256(byte[] bytes)
        {
            using (SHA256 hash = SHA256.Create())
                return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-", "").ToLowerInvariant();
        }

        // Validate the complete archive before writing any archive member.
        internal static string Extract(byte[] bytes, string expectedHash, string rootName, string destination)
        {
            if (bytes.LongLength > MaximumZipBytes ||
                !String.Equals(Sha256(bytes), expectedHash, StringComparison.OrdinalIgnoreCase))
                throw new InvalidDataException("Встроенный архив повреждён: SHA-256 не совпал.");
            if (!Regex.IsMatch(rootName, @"^AntiDPI_CLI_v[0-9]+(?:\.[0-9]+){1,3}_Windows_x64$"))
                throw new InvalidDataException("Недопустимое имя корневой папки архива.");

            string prefix = rootName + "/";
            string root = Path.GetFullPath(destination).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
            Dictionary<string, bool> paths = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> entries = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            bool hasManager = false;
            bool hasInstaller = false;
            long total = 0;
            using (MemoryStream memory = new MemoryStream(bytes, false))
            using (ZipArchive zip = new ZipArchive(memory, ZipArchiveMode.Read, false, Encoding.UTF8))
            {
                if (zip.Entries.Count == 0 || zip.Entries.Count > 10000)
                    throw new InvalidDataException("Недопустимое число файлов во встроенном архиве.");
                List<string> targets = new List<string>();
                foreach (ZipArchiveEntry entry in zip.Entries)
                {
                    string name = entry.FullName;
                    if (!name.StartsWith(prefix, StringComparison.Ordinal) || name.IndexOf('\\') >= 0 || !entries.Add(name))
                        throw new InvalidDataException("Недопустимый или повторяющийся путь в архиве: " + name);
                    bool directory = name.EndsWith("/", StringComparison.Ordinal);
                    string relative = directory ? name.Substring(0, name.Length - 1) : name;
                    string[] parts = relative.Split('/');
                    for (int n = 0; n < parts.Length; n++)
                    {
                        string part = parts[n];
                        if (part.Length == 0 || part == "." || part == ".." ||
                            part.EndsWith(".", StringComparison.Ordinal) || part.EndsWith(" ", StringComparison.Ordinal) ||
                            DeviceName.IsMatch(part))
                            throw new InvalidDataException("Недопустимый компонент пути в архиве: " + name);
                        foreach (char c in part)
                            if (c < 32 || ":*?\"<>|".IndexOf(c) >= 0)
                                throw new InvalidDataException("Недопустимый символ в пути архива: " + name);
                    }
                    int kind = (entry.ExternalAttributes >> 16) & 0xF000;
                    if (kind != 0 && kind != 0x8000 && kind != 0x4000)
                        throw new InvalidDataException("Ссылки и специальные файлы в архиве запрещены: " + name);
                    if ((kind == 0x4000 && !directory) || (kind == 0x8000 && directory) ||
                        (directory && entry.Length != 0))
                        throw new InvalidDataException("Некорректный тип элемента архива: " + name);
                    total += entry.Length;
                    if (entry.Length > MaximumExpandedBytes || total > MaximumExpandedBytes)
                        throw new InvalidDataException("Превышен допустимый размер распакованного архива.");

                    for (int n = 1; n <= parts.Length; n++)
                    {
                        string key = String.Join("/", parts, 0, n);
                        bool isDirectory = n < parts.Length || directory;
                        bool existing;
                        if (paths.TryGetValue(key, out existing) && (!existing || !isDirectory))
                            throw new InvalidDataException("Конфликт файла и папки в архиве: " + name);
                        paths[key] = isDirectory;
                    }
                    string target = Path.GetFullPath(Path.Combine(destination, relative.Replace('/', Path.DirectorySeparatorChar)));
                    if (!target.StartsWith(root, StringComparison.OrdinalIgnoreCase))
                        throw new InvalidDataException("Путь выходит за пределы временной папки.");
                    if (target.Length > (directory ? 247 : 259) || Path.GetDirectoryName(target).Length > 247)
                        throw new PathTooLongException("Выберите более короткий путь для временных файлов установщика.");
                    if (name == prefix + "AntiDPI_Manager.ps1" && !directory) hasManager = true;
                    if (name == prefix + "AntiDPI_Installer.ps1" && !directory) hasInstaller = true;
                    targets.Add(target);
                }
                if (!hasManager || !hasInstaller) throw new InvalidDataException("Во встроенном архиве отсутствует установщик AntiDPI.");
                for (int n = 0; n < zip.Entries.Count; n++)
                {
                    ZipArchiveEntry entry = zip.Entries[n];
                    string target = targets[n];
                    if (entry.FullName.EndsWith("/", StringComparison.Ordinal))
                    {
                        Directory.CreateDirectory(target);
                        continue;
                    }
                    Directory.CreateDirectory(Path.GetDirectoryName(target));
                    using (Stream source = entry.Open())
                    using (FileStream output = new FileStream(target, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                    {
                        byte[] buffer = new byte[65536];
                        long written = 0;
                        int count;
                        while ((count = source.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            written += count;
                            if (written > entry.Length) throw new InvalidDataException("Некорректная длина файла в архиве.");
                            output.Write(buffer, 0, count);
                        }
                        if (written != entry.Length) throw new InvalidDataException("Архив содержит неполный файл.");
                    }
                }
            }
            return Path.Combine(destination, rootName, "AntiDPI_Manager.ps1");
        }
    }

    internal sealed class Workspace
    {
        internal string DirectoryPath;
        internal string Token;
        private const string Marker = ".antidpi-setup-owned";

        internal static Workspace Create()
        {
            string systemDrive = Path.GetPathRoot(Environment.GetFolderPath(Environment.SpecialFolder.Windows));
            string[] parents = { systemDrive, Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData) };
            Exception last = null;
            foreach (string parent in parents)
            {
                if (String.IsNullOrEmpty(parent)) continue;
                string token = Guid.NewGuid().ToString("N");
                string path = Path.Combine(parent, ".ig-" + token.Substring(0, 16));
                if (Directory.Exists(path) || File.Exists(path)) continue;
                bool created = false;
                try
                {
                    DirectorySecurity acl = new DirectorySecurity();
                    acl.SetAccessRuleProtection(true, false);
                    SecurityIdentifier user = WindowsIdentity.GetCurrent().User;
                    acl.SetOwner(user);
                    foreach (SecurityIdentifier sid in new SecurityIdentifier[] {
                        user, new SecurityIdentifier("S-1-5-18"), new SecurityIdentifier("S-1-5-32-544") })
                        acl.AddAccessRule(new FileSystemAccessRule(sid, FileSystemRights.FullControl,
                            InheritanceFlags.ContainerInherit | InheritanceFlags.ObjectInherit,
                            PropagationFlags.None, AccessControlType.Allow));
                    Directory.CreateDirectory(path, acl);
                    created = true;
                    if ((File.GetAttributes(path) & FileAttributes.ReparsePoint) != 0)
                        throw new IOException("Временная папка является ссылкой.");
                    using (FileStream marker = new FileStream(Path.Combine(path, Marker), FileMode.CreateNew, FileAccess.Write))
                    using (StreamWriter writer = new StreamWriter(marker, new UTF8Encoding(false))) writer.Write(token);
                    return new Workspace { DirectoryPath = path, Token = token };
                }
                catch (Exception error)
                {
                    last = error;
                    if (created) { try { Directory.Delete(path, false); } catch { } }
                }
            }
            throw new IOException("Не удалось создать короткую временную папку установщика.", last);
        }

        internal void Delete()
        {
            if (!Directory.Exists(DirectoryPath)) return;
            if ((File.GetAttributes(DirectoryPath) & FileAttributes.ReparsePoint) != 0 ||
                Path.GetFileName(DirectoryPath) != ".ig-" + Token.Substring(0, 16) ||
                File.ReadAllText(Path.Combine(DirectoryPath, Marker), Encoding.UTF8) != Token)
                throw new IOException("Отказ от удаления посторонней временной папки.");
            DeleteTree(DirectoryPath);
        }

        private static void DeleteTree(string path)
        {
            foreach (string child in Directory.GetFileSystemEntries(path))
            {
                FileAttributes attributes = File.GetAttributes(child);
                if ((attributes & FileAttributes.ReparsePoint) != 0)
                    throw new IOException("Отказ от перехода по ссылке при очистке: " + child);
                if ((attributes & FileAttributes.Directory) != 0) DeleteTree(child);
                else { File.SetAttributes(child, FileAttributes.Normal); File.Delete(child); }
            }
            Directory.Delete(path, false);
        }
    }

    internal static class Program
    {
        private static string logPath;

        [STAThread]
        private static int Main()
        {
            Workspace work = null;
            bool childFinished = true;
            try
            {
                RequireSupportedWindows();
                if (!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))
                    throw new InvalidOperationException("Подтвердите запуск установщика от имени Администратора.");
                string logs = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "AntiDPI_Install_Logs");
                Directory.CreateDirectory(logs);
                logPath = Path.Combine(logs, "Setup_CLI_" + BuildInfo.Version + "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss_fff") + "_" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".log");
                Log("CLI Version " + BuildInfo.Version + "; Windows x64; verifying embedded installer.");
                byte[] payload = Payload.ReadEmbedded(Assembly.GetExecutingAssembly());
                if (!String.Equals(Payload.Sha256(payload), BuildInfo.PayloadSha256, StringComparison.OrdinalIgnoreCase))
                    throw new InvalidDataException("Встроенный архив повреждён: SHA-256 не совпал.");
                work = Workspace.Create();
                string manager = Payload.Extract(payload, BuildInfo.PayloadSha256, BuildInfo.PayloadRoot, work.DirectoryPath);
                Log("Embedded ZIP and extracted paths verified.");
                string system = Environment.GetFolderPath(Environment.SpecialFolder.System);
                string powershell = Path.Combine(system, "WindowsPowerShell", "v1.0", "powershell.exe");
                string installer = Path.Combine(Path.GetDirectoryName(manager), "AntiDPI_Installer.ps1");
                if (!File.Exists(powershell) || !File.Exists(installer))
                    throw new FileNotFoundException("Не найдены штатный Windows PowerShell или графический установщик AntiDPI.");
                StringBuilder command = new StringBuilder(Quote(powershell) +
                    " -NoLogo -NoProfile -STA -ExecutionPolicy Bypass -File " + Quote(installer));
                Native.StartupInfo startup = new Native.StartupInfo();
                startup.cb = Marshal.SizeOf(typeof(Native.StartupInfo));
                Native.ProcessInformation process;
                Log("Starting the Windows GUI installer in a visible console.");
                // CREATE_NEW_CONSOLE: don't suppress PowerShell while the user installs the program.
                if (!Native.CreateProcess(powershell, command, IntPtr.Zero, IntPtr.Zero, false, 0x00000010,
                    IntPtr.Zero, Path.GetDirectoryName(manager), ref startup, out process))
                    throw new Win32Exception(Marshal.GetLastWin32Error(), "Не удалось запустить графический установщик.");
                childFinished = false;
                try
                {
                    Native.CloseHandle(process.hThread);
                    if (Native.WaitForSingleObject(process.hProcess, 0xFFFFFFFFU) != 0)
                        throw new Win32Exception(Marshal.GetLastWin32Error(), "Не удалось дождаться завершения установщика.");
                    childFinished = true;
                    uint exitCode;
                    if (!Native.GetExitCodeProcess(process.hProcess, out exitCode))
                        throw new Win32Exception(Marshal.GetLastWin32Error());
                    Log("Installer console exit code: " + exitCode);
                    if (exitCode != 0) throw new InvalidOperationException("Установщик завершился с кодом " + exitCode + ". Сохраните его консольный лог.");
                }
                finally { Native.CloseHandle(process.hProcess); }
                return 0;
            }
            catch (Exception error)
            {
                Log(error.ToString());
                string message = error.Message;
                if (!String.IsNullOrEmpty(logPath)) message += "\r\n\r\nЛог: " + logPath;
                Native.MessageBox(IntPtr.Zero, message, "AntiDPI CLI Version " + BuildInfo.Version, 0x10);
                return 1;
            }
            finally
            {
                if (work != null && childFinished)
                    try { work.Delete(); } catch (Exception error) { Log("Temporary cleanup: " + error.Message); }
            }
        }

        internal static string Quote(string value)
        {
            StringBuilder result = new StringBuilder("\"");
            int slashes = 0;
            foreach (char c in value)
            {
                if (c == '\\') { slashes++; continue; }
                if (c == '"') result.Append('\\', slashes * 2 + 1);
                else result.Append('\\', slashes);
                result.Append(c);
                slashes = 0;
            }
            result.Append('\\', slashes * 2).Append('"');
            return result.ToString();
        }

        private static void RequireSupportedWindows()
        {
            if (Environment.OSVersion.Platform != PlatformID.Win32NT || !Environment.Is64BitOperatingSystem || Environment.OSVersion.Version.Major < 10)
                throw new PlatformNotSupportedException("Нужна Windows 10/11 x64.");
            try
            {
                ushort process, native;
                if (Native.IsWow64Process2(Native.GetCurrentProcess(), out process, out native) && native != 0x8664)
                    throw new PlatformNotSupportedException("Эта сборка предназначена для Windows x64, а не ARM64 или x86.");
            }
            catch (EntryPointNotFoundException)
            {
                if (String.Equals(Environment.GetEnvironmentVariable("PROCESSOR_ARCHITEW6432"), "ARM64", StringComparison.OrdinalIgnoreCase) ||
                    String.Equals(Environment.GetEnvironmentVariable("PROCESSOR_ARCHITECTURE"), "ARM64", StringComparison.OrdinalIgnoreCase))
                    throw new PlatformNotSupportedException("Эта сборка не предназначена для ARM64.");
            }
        }

        private static void Log(string text)
        {
            if (String.IsNullOrEmpty(logPath)) return;
            try { File.AppendAllText(logPath, DateTime.UtcNow.ToString("o") + " " + text + Environment.NewLine, new UTF8Encoding(false)); }
            catch { }
        }
    }

    internal static class Native
    {
        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        internal struct StartupInfo
        {
            internal int cb;
            internal string lpReserved, lpDesktop, lpTitle;
            internal int dwX, dwY, dwXSize, dwYSize, dwXCountChars, dwYCountChars, dwFillAttribute, dwFlags;
            internal short wShowWindow, cbReserved2;
            internal IntPtr lpReserved2, hStdInput, hStdOutput, hStdError;
        }
        [StructLayout(LayoutKind.Sequential)]
        internal struct ProcessInformation
        {
            internal IntPtr hProcess, hThread;
            internal uint dwProcessId, dwThreadId;
        }
        [DllImport("kernel32.dll", EntryPoint = "CreateProcessW", CharSet = CharSet.Unicode, SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        internal static extern bool CreateProcess(string application, StringBuilder command, IntPtr processAttributes,
            IntPtr threadAttributes, bool inheritHandles, uint flags, IntPtr environment, string directory,
            ref StartupInfo startup, out ProcessInformation information);
        [DllImport("kernel32.dll", SetLastError = true)] internal static extern uint WaitForSingleObject(IntPtr handle, uint milliseconds);
        [DllImport("kernel32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)]
        internal static extern bool GetExitCodeProcess(IntPtr process, out uint code);
        [DllImport("kernel32.dll")] [return: MarshalAs(UnmanagedType.Bool)] internal static extern bool CloseHandle(IntPtr handle);
        [DllImport("kernel32.dll")] internal static extern IntPtr GetCurrentProcess();
        [DllImport("kernel32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)]
        internal static extern bool IsWow64Process2(IntPtr process, out ushort processMachine, out ushort nativeMachine);
        [DllImport("user32.dll", EntryPoint = "MessageBoxW", CharSet = CharSet.Unicode)]
        internal static extern int MessageBox(IntPtr window, string text, string title, uint type);
    }
}
